import apps.core.stores
import django.db.models.deletion
import re

from django.db import migrations, models
from django.utils.text import slugify


SPLIT = re.compile(r"\s*[،,]\s*")
LAYERS = (("notes_top", "top"), ("notes_middle", "heart"), ("notes_base", "base"))


def copy_text_notes_to_structured(apps, schema_editor):
    """«برگاموت، هل» در notes_top ← FragranceNote «برگاموت» و «هل» + ProductNote(layer=top)."""
    Product = apps.get_model("catalog", "Product")
    FragranceNote = apps.get_model("catalog", "FragranceNote")
    ProductNote = apps.get_model("catalog", "ProductNote")
    for product in Product.objects.all():
        for field, layer in LAYERS:
            names = [n for n in SPLIT.split(getattr(product, field) or "") if n]
            for order, name in enumerate(names):
                slug = slugify(name, allow_unicode=True) or f"note-{abs(hash(name))}"
                note, _ = FragranceNote.objects.get_or_create(
                    store_id=product.store_id, slug=slug, defaults={"name": name}
                )
                ProductNote.objects.get_or_create(product=product, note=note, layer=layer, defaults={"order": order})


def restore_text_notes(apps, schema_editor):
    Product = apps.get_model("catalog", "Product")
    ProductNote = apps.get_model("catalog", "ProductNote")
    for product in Product.objects.all():
        links = ProductNote.objects.filter(product_id=product.pk).select_related("note").order_by("order", "id")
        for field, layer in LAYERS:
            setattr(product, field, "، ".join(l.note.name for l in links if l.layer == layer))
        product.save(update_fields=[f for f, _ in LAYERS])


